v446-global-combat-power-authority.body:
(function(){
  const VERSION='V4.67 Stable', SHORT='V4.67';
  let ownProfileOpenId='', syncTimer=0, syncBusy=false, lastSyncedPower=null, painting=false;

  /* ONE combat-power source for the whole game: exactly the same global function
     that paints #charPower on the character page. */
  function livePower(){
    try{return Math.max(0,Math.round(Number(combatPower())||0))}catch(e){return 0}
  }
  window.v446CombatPower=livePower;

  /* Remove the last historical second formula. Any old profile code that still
     calls v074CombatPower now receives the character-page value too. */
  try{
    v074CombatPower=function(){return livePower()};
    window.v074CombatPower=v074CombatPower;
  }catch(e){}

  /* Every profile write, regardless of which historical wrapper owns it, carries
     the exact current combatPower(). */
  if(typeof v073ProfilePayload==='function'&&!window.__v446ProfilePayloadWrapped){
    const basePayload=v073ProfilePayload;
    v073ProfilePayload=function(){
      const p=basePayload.apply(this,arguments)||{};
      p.combat_power=livePower();
      return p;
    };
    try{window.v073ProfilePayload=v073ProfilePayload}catch(e){}
    window.__v446ProfilePayloadWrapped=true;
  }

  function ownUserId(){
    try{return typeof v073User!=='undefined'&&v073User?.id?String(v073User.id):''}catch(e){return ''}
  }
  function setText(el,value){
    if(!el)return;
    const v=String(value);
    if(el.textContent!==v)el.textContent=v;
  }
  function replacePowerText(el,cp){
    if(!el)return;
    const txt=String(el.textContent||'');
    if(/Kampfkraft\s*[\d.]+/i.test(txt)){
      const next=txt.replace(/Kampfkraft\s*[\d.]+/i,`Kampfkraft ${cp}`);
      if(next!==txt)el.textContent=next;
    }
  }
  function paintProfileStat(root,cp){
    if(!root)return;
    [...root.querySelectorAll('.v326-profile-stat,.v072-profile-stat,.v074-power')].forEach(box=>{
      if(!/Kampf(?:kraft|wert)/i.test(box.textContent||''))return;
      const b=box.querySelector('b');
      if(b)setText(b,cp);
    });
  }

  function paintLocalPower(){
    if(painting)return;
    painting=true;
    try{
      const cp=livePower();

      /* Character / legacy header / global header / worldboss. */
      ['#power','#charPower','#v358Power','#v110Cp'].forEach(sel=>setText(document.querySelector(sel),cp));

      /* World layouts that already intend to show the player's own power. */
      document.querySelectorAll('.v349-power b,.v366-power b,.v251-detail-bottom .v251-mini-stat:first-child b')
        .forEach(el=>setText(el,cp));

      /* PvP: only the local/player side. Enemy power remains the opponent's synced value. */
      replacePowerText(document.querySelector('#v209PlayerSub'),cp);

      const uid=ownUserId();
      if(uid){
        /* Hall/search rows for the logged-in user. Closed-over historical row renderers
           are corrected at DOM level, so they cannot reintroduce a cached DB value. */
        document.querySelectorAll('.v072-player-row[data-profile-id]').forEach(row=>{
          if(String(row.getAttribute('data-profile-id')||'')!==uid)return;
          const sub=row.querySelector('.v072-player-sub');
          if(sub)replacePowerText(sub,cp);
        });

        paintProfileStat(document.querySelector('#v072OwnProfile'),cp);
        if(String(ownProfileOpenId||'')===uid)paintProfileStat(document.querySelector('#v074ProfileContent'),cp);

        /* Guild boss participant/test rows may contain the local player as a server
           snapshot. Repaint only when the participant object can be tied to our user id. */
        try{
          if(Array.isArray(v255BossParticipants))v255BossParticipants.forEach(x=>{
            if(String(x?.user_id||x?.id||'')===uid)x.combat_power=cp;
          });
        }catch(e){}
        try{
          if(Array.isArray(v254Members))v254Members.forEach(m=>{
            if(String(m?.user_id||'')===uid&&m.profile)m.profile.combat_power=cp;
          });
        }catch(e){}
      }
    }finally{painting=false}
  }
  window.v446PaintCombatPower=paintLocalPower;

  /* Direct server repair. This is independent of legacy sync return values and makes
     Hall/PvP/Guild reads use the same formula for this player. */
  async function writeLivePower(force=false){
    if(syncBusy)return true;
    try{
      if(typeof v073Init==='function')await v073Init();
      if(typeof v073Db==='undefined'||!v073Db||typeof v073User==='undefined'||!v073User||v073User.is_anonymous)return false;
      if(!s?.characterNameSet)return false;
      if(typeof v071NameValid==='function'&&!v071NameValid(s.characterName))return false;
      const cp=livePower();
      if(!force&&lastSyncedPower===cp)return true;
      syncBusy=true;
      const {error}=await window.v7101ProfileUpdate({combat_power:cp,updated_at:new Date().toISOString()}).eq('id',v073User.id);
      if(error)throw error;
      lastSyncedPower=cp;
      return true;
    }catch(e){
      console.warn('V4.46 combat power sync',e);
      return false;
    }finally{syncBusy=false}
  }
  window.v446SyncCombatPower=writeLivePower;

  function scheduleSync(force=false){
    clearTimeout(syncTimer);
    syncTimer=setTimeout(async()=>{
      await writeLivePower(force);
      paintLocalPower();
    },force?0:450);
  }

  /* Ensure profile sync itself cannot finish with another combat-power value. */
  if(typeof v073SyncProfile==='function'&&!window.__v446ProfileSyncWrapped){
    const baseSync=v073SyncProfile;
    v073SyncProfile=async function(force=false){
  if(window.__V200_AUTH_READY__!==true)return false;
      let ok=false;
      try{ok=!!(await baseSync.apply(this,arguments))}catch(e){console.warn('V4.46 base profile sync',e)}
      const powerOk=await writeLivePower(!!force);
      paintLocalPower();
      return ok||powerOk;
    };
    try{window.v073SyncProfile=v073SyncProfile}catch(e){}
    window.__v446ProfileSyncWrapped=true;
  }

  /* Public profile modal: own profile is live; other players keep their own synced DB value. */
  if(typeof v074OpenProfile==='function'&&!window.__v446OpenProfileWrapped){
    const baseOpen=v074OpenProfile;
    v074OpenProfile=async function(id){
      ownProfileOpenId=String(id||'');
      const own=ownUserId()&&ownProfileOpenId===ownUserId();
      if(own)await writeLivePower(true);
      const r=await baseOpen.apply(this,arguments);
      if(own){paintLocalPower();requestAnimationFrame(paintLocalPower);setTimeout(paintLocalPower,80)}
      return r;
    };
    try{window.v074OpenProfile=v074OpenProfile}catch(e){}
    window.__v446OpenProfileWrapped=true;
  }

  /* Existing own-row renderer, if called directly, gets the same value before HTML is built. */
  if(typeof v073PlayerRow==='function'&&!window.__v446PlayerRowWrapped){
    const baseRow=v073PlayerRow;
    v073PlayerRow=function(p,i,actions){
      const uid=ownUserId();
      if(p&&uid&&String(p.id||'')===uid)p={...p,combat_power:livePower()};
      return baseRow.call(this,p,i,actions);
    };
    try{window.v073PlayerRow=v073PlayerRow}catch(e){}
    window.__v446PlayerRowWrapped=true;
  }

  /* Local changes (level, attributes, equipment, gems/scrolls, talents) all persist.
     Repaint instantly and debounce one server write. */
  if(typeof persist==='function'&&!window.__v446PersistWrapped){
    const basePersist=persist;
    persist=function(){
      const r=basePersist.apply(this,arguments);
      paintLocalPower();
      requestAnimationFrame(paintLocalPower);
      scheduleSync(false);
      stamp();
      return r;
    };
    try{window.persist=persist}catch(e){}
    window.__v446PersistWrapped=true;
  }

  if(typeof render==='function'&&!window.__v446RenderWrapped){
    const baseRender=render;
    render=function(){
      const r=baseRender.apply(this,arguments);
      paintLocalPower();
      requestAnimationFrame(paintLocalPower);
      stamp();
      return r;
    };
    try{window.render=render}catch(e){}
    window.__v446RenderWrapped=true;
  }

  if(typeof v032Go==='function'&&!window.__v446GoWrapped){
    const baseGo=v032Go;
    v032Go=function(id){
      const r=baseGo.apply(this,arguments);
      requestAnimationFrame(paintLocalPower);
      setTimeout(paintLocalPower,80);
      if(['hall','pvp','guild','friends','character','world'].includes(String(id||'')))scheduleSync(false);
      return r;
    };
    try{window.v032Go=v032Go}catch(e){}
    window.__v446GoWrapped=true;
  }

  if(typeof v110Refresh==='function'&&!window.__v446WorldbossWrapped){
    const baseRefresh=v110Refresh;
    v110Refresh=function(){
      const r=baseRefresh.apply(this,arguments);
      paintLocalPower();
      return r;
    };
    try{window.v110Refresh=v110Refresh}catch(e){}
    window.__v446WorldbossWrapped=true;
  }

  if(typeof v255RenderBoss==='function'&&!window.__v446GuildBossRenderWrapped){
    const baseBoss=v255RenderBoss;
    v255RenderBoss=function(){paintLocalPower();const r=baseBoss.apply(this,arguments);paintLocalPower();return r};
    try{window.v255RenderBoss=v255RenderBoss}catch(e){}
    window.__v446GuildBossRenderWrapped=true;
  }

  function stamp(){}

  paintLocalPower();stamp();scheduleSync(true);
  document.addEventListener('DOMContentLoaded',()=>{paintLocalPower();stamp();scheduleSync(true)},{once:true});
  window.addEventListener('pageshow',()=>{paintLocalPower();stamp();scheduleSync(true)},{passive:true});
  document.addEventListener('click',()=>{requestAnimationFrame(paintLocalPower);setTimeout(paintLocalPower,60)},true);
  setTimeout(()=>{paintLocalPower();stamp();scheduleSync(true)},600);
  setTimeout(()=>{paintLocalPower();stamp()},1800);
  setTimeout(()=>{paintLocalPower();stamp();scheduleSync(true)},5200);
  /* V4.86: retired 18 s combat-power polling guard. Event/render hooks above are authoritative. */
})();

v652-player-profile-redesign-js.body:
(()=>{
  'use strict';
  const VERSION='V6.52';
  function classIdFromText(text){
    const t=String(text||'').toLowerCase();
    if(t.includes('harzrufer'))return 'summoner';
    if(t.includes('frost')||t.includes('todesritter'))return 'frost';
    if(t.includes('blatt-schütze')||t.includes('blatt-schutze')||t.includes('schütze')||t.includes('schutze'))return 'scout';
    if(t.includes('magier'))return 'bruiser';
    return 'grower';
  }
  function decorateProfile(){
    const content=document.querySelector('#v074ProfileContent');
    const modal=document.querySelector('#v074ProfileOverlay .v074-profile-modal');
    if(!content||!modal)return;
    content.classList.add('v652-profile');

    let banner=content.querySelector(':scope > .v652-profile-banner');
    const head=content.querySelector('.v074-profile-head');
    const close=content.querySelector('#v074CloseBtn')||content.querySelector('.v074-close');
    if(!banner){
      banner=document.createElement('div');
      banner.className='v652-profile-banner';
      banner.innerHTML='<span>Spielerprofil</span>';
      content.insertBefore(banner,content.firstChild);
    }
    if(close&&close.parentElement!==banner)banner.appendChild(close);

    if(head){
      const info=head.querySelector(':scope > div:not(.v652-profile-avatar):not(.v326-profile-stat)');
      if(!head.querySelector('.v652-profile-avatar')){
        const cls=classIdFromText(content.querySelector('.v074-profile-class')?.textContent);
        const av=document.createElement('div');
        av.className='v652-profile-avatar';
        let src='';
        try{src=typeof v080AvatarFor==='function'?v080AvatarFor(cls):''}catch(e){}
        av.innerHTML=src?`<img src="${src}" alt="Spieleravatar">`:'<div class="v652-profile-avatar-fallback">🌿</div>';
        if(info)head.insertBefore(av,info);else head.prepend(av);
      }
      const topGrid=content.querySelector(':scope > .v326-profile-grid');
      const power=topGrid?.querySelector(':scope > .v326-profile-stat:first-child');
      if(power&&!head.querySelector('.v652-head-power')){
        power.classList.add('v652-head-power');
        head.appendChild(power);
      }
    }

    const mystic=content.querySelector(':scope > .v326-mystic');
    const pvp=content.querySelector(':scope > .v326-pvp');
    if(mystic&&pvp&&!mystic.parentElement.classList.contains('v652-profile-dual')){
      const dual=document.createElement('div');
      dual.className='v652-profile-dual';
      mystic.parentNode.insertBefore(dual,mystic);
      dual.append(mystic,pvp);
    }

    const title=[...content.querySelectorAll('h3')].find(x=>/Angelegte Ausrüstung/i.test(x.textContent||''));
    if(title)title.classList.add('v652-equipment-title');
  }

  let queued=0;
  function queueDecorate(resetScroll=false){
    if(queued)cancelAnimationFrame(queued);
    queued=requestAnimationFrame(()=>{
      queued=0;decorateProfile();
      if(resetScroll){const m=document.querySelector('#v074ProfileOverlay .v074-profile-modal');if(m)m.scrollTop=0}
    });
  }

  try{
    if(typeof v074OpenProfile==='function'&&!window.__v652PlayerProfileWrapped){
      const base=v074OpenProfile;
      const wrapped=async function(){
        const overlay=document.querySelector('#v074ProfileOverlay');
        const modal=overlay?.querySelector('.v074-profile-modal');
        if(modal)modal.scrollTop=0;
        const r=await base.apply(this,arguments);
        queueDecorate(true);
        setTimeout(()=>queueDecorate(false),40);
        return r;
      };
      wrapped.__v652=true;
      v074OpenProfile=wrapped;
      try{window.v074OpenProfile=wrapped}catch(e){}
      window.__v652PlayerProfileWrapped=true;
    }
  }catch(e){console.warn(VERSION+' profile wrapper',e)}

  const content=document.querySelector('#v074ProfileContent');
  if(content){
    const mo=new MutationObserver(()=>queueDecorate(false));
    mo.observe(content,{childList:true,subtree:true});
  }
  document.addEventListener('click',e=>{
    if(e.target.closest?.('.v072-player-row[data-profile-id]'))setTimeout(()=>queueDecorate(true),0);
  },true);
})();

v655-player-profile-load-fix-js.body:
(()=>{
  'use strict';
  const VERSION='V6.55';
  let requestSeq=0;

  const esc=v=>{
    try{return typeof v073Escape==='function'?v073Escape(v):String(v??'')}
    catch(e){return String(v??'')}
  };
  const num=v=>Math.max(0,Math.round(Number(v)||0));
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,Math.round(Number(v)||0)));

  function overlayParts(){
    return {
      overlay:document.querySelector('#v074ProfileOverlay'),
      content:document.querySelector('#v074ProfileContent'),
      modal:document.querySelector('#v074ProfileOverlay .v074-profile-modal')
    };
  }

  function wireClose(){
    const btn=document.querySelector('#v074CloseBtn');
    if(btn)btn.onclick=()=>{requestSeq++; try{v074CloseProfile()}catch(e){document.querySelector('#v074ProfileOverlay')?.classList.remove('show')}};
  }

  function showLoading(){
    const {overlay,content,modal}=overlayParts();
    if(!overlay||!content)return false;
    overlay.classList.add('show');
    if(modal)modal.scrollTop=0;
    content.innerHTML=`
      <button class="btn secondary v074-close" id="v074CloseBtn" aria-label="Spielerprofil schließen">✕</button>
      <div class="v655-profile-loading">
        <div class="v655-profile-spinner" aria-hidden="true"></div>
        <div>Spielerprofil wird geladen...</div>
      </div>`;
    wireClose();
    return true;
  }

  function showError(id,message){
    const {content}=overlayParts();
    if(!content)return;
    content.innerHTML=`
      <button class="btn secondary v074-close" id="v074CloseBtn" aria-label="Spielerprofil schließen">✕</button>
      <div class="v655-profile-error">
        <strong>Profil konnte nicht geladen werden.</strong>
        <div>${esc(message||'Die Online-Verbindung antwortet gerade nicht.')}</div>
        <div class="v655-profile-actions">
          <button class="btn" id="v655ProfileRetry">Erneut versuchen</button>
          <button class="btn secondary" id="v655ProfileClose">Schließen</button>
        </div>
      </div>`;
    wireClose();
    document.querySelector('#v655ProfileRetry')?.addEventListener('click',()=>v074OpenProfile(id));
    document.querySelector('#v655ProfileClose')?.addEventListener('click',()=>{requestSeq++;try{v074CloseProfile()}catch(e){document.querySelector('#v074ProfileOverlay')?.classList.remove('show')}});
  }

  function dungeonPos(p){
    const dp=(p&&p.dungeon_progress&&typeof p.dungeon_progress==='object')?p.dungeon_progress:{};
    try{
      if(typeof v081DungeonPosition==='function'){
        const x=v081DungeonPosition(dp,Number(p?.dungeons)||0);
        if(x&&Number.isFinite(Number(x.dungeonIndex)))return x;
      }
    }catch(e){}
    const completed=Array.isArray(dp.completed)?dp.completed.map(Number).filter(Number.isFinite):[];
    let idx=clamp(dp.lastActive ?? dp.selected ?? completed.length,0,19);
    let room=Number(dp.progress?.[idx]);
    if(!Number.isFinite(room))room=(Number(dp.selected)===idx?Number(dp.room):0);
    room=clamp(room,0,9);
    return {dungeonIndex:idx,dungeonNumber:idx+1,enemyNumber:room+1,completed:completed.includes(idx)};
  }

  function equipmentHtml(eq){
    try{return typeof v074EquipmentHtml==='function'?v074EquipmentHtml(eq||{}):'<div class="v072-empty">Keine Ausrüstung sichtbar.</div>'}
    catch(e){return '<div class="v072-empty">Ausrüstung konnte nicht angezeigt werden.</div>'}
  }

  function renderProfile(p){
    const {content,modal}=overlayParts();
    if(!content||!p)return;
    const pos=dungeonPos(p);
    const dp=(p.dungeon_progress&&typeof p.dungeon_progress==='object')?p.dungeon_progress:{};
    const publicTitle=String(dp?.public_title?.label||'');
    const completed=Array.isArray(dp.completed)?dp.completed.length:num(p.dungeons);
    const wbAttempts=num(p.worldboss_attempts), wbWins=num(p.worldboss_wins);
    const pvpWins=num(p.pvp_wins), pvpLosses=num(p.pvp_losses);
    const pvpFights=Math.max(num(p.pvp_fights),pvpWins+pvpLosses);
    const petStats=(dp.pet_stats&&typeof dp.pet_stats==='object')?dp.pet_stats:{};
    const petRows=Math.max(0,Math.min(20,num(petStats.rows)));
    const petFound=Math.max(0,Math.min(120,num(petStats.found)));
    let dungeonName=`Dungeon ${pos.dungeonNumber}`;
    try{if(typeof dungeons!=='undefined'&&dungeons?.[pos.dungeonIndex]?.name)dungeonName=dungeons[pos.dungeonIndex].name}catch(e){}
    let own=false;
    try{own=!!v073User?.id&&String(p.id||'')===String(v073User.id)}catch(e){}

    content.innerHTML=`
      <div class="v074-profile-head">
        <div>
          <div class="v074-profile-title">${esc(p.character_name||'Spieler')}</div>
          ${publicTitle?`<div class="v6338-profile-title">👑 ${esc(publicTitle)}</div>`:''}
          <div class="v074-profile-class">${esc(p.class_name||'')} · Level ${Math.max(1,num(p.level))}</div>
        </div>
        <button class="btn secondary v074-close" id="v074CloseBtn" aria-label="Spielerprofil schließen">✕</button>
      </div>

      <div class="v326-profile-grid">
        <div class="v326-profile-stat"><span>⚔️ Kampfkraft</span><b>${num(p.combat_power)}</b></div>
        <div class="v326-profile-stat"><span>🎒 Ausrüstung</span><b>${num(p.gear_score)}</b></div>
        <div class="v326-profile-stat"><span>🌿 PvP-Buds</span><b>${num(p.pvp_buds)}</b></div>
        <div class="v326-profile-stat"><span>🗺️ Dungeon</span><b>${pos.dungeonNumber}</b></div>
        <div class="v326-profile-stat"><span>👹 Gegner</span><b>${pos.enemyNumber}/10</b></div>
        <div class="v326-profile-stat"><span>🏁 Abgeschlossen</span><b>${completed}</b></div>
      </div>

      <div class="v326-section">
        <div class="v326-section-title">🗺️ Aktueller Dungeon-Fortschritt</div>
        <div class="v326-dungeon">Dungeon ${pos.dungeonNumber} · ${esc(dungeonName)} · ${pos.completed?'10/10 abgeschlossen':`${pos.enemyNumber}/10`}</div>
      </div>

      <div class="v326-section v326-mystic">
        <div class="v326-section-title">🔷 Mystischer Weltboss · Smaragd-Koloss</div>
        <div class="v326-profile-grid" style="margin:0">
          <div class="v326-profile-stat"><span>Versuche</span><b>${wbAttempts}</b></div>
          <div class="v326-profile-stat"><span>Siege</span><b>${wbWins}</b></div>
        </div>
        <div class="v326-profile-note">Gesamtwerte des Spielers.</div>
      </div>

      <div class="v326-section v326-pvp">
        <div class="v326-section-title">⚔️ PvP</div>
        <div class="v326-profile-grid" style="margin:0">
          <div class="v326-profile-stat"><span>Kämpfe</span><b>${pvpFights}</b></div>
          <div class="v326-profile-stat"><span>Siege</span><b>${pvpWins}</b></div>
          <div class="v326-profile-stat"><span>Niederlagen</span><b>${pvpLosses}</b></div>
        </div>
      </div>

      <div class="v326-section v6113-profile-pets">
        <div class="v326-section-title">🐾 Pet Sammelalbum</div>
        <div class="v6113-pet-profile-grid">
          <div class="v6113-pet-profile-stat">
            <span>📚 Gesammelte Pet-Reihen</span>
            <b>${petRows}<small>/20</small></b>
          </div>
          <div class="v6113-pet-profile-stat">
            <span>🐾 Gefundene Pets</span>
            <b>${petFound}<small>/120</small></b>
          </div>
        </div>
        <div class="v326-profile-note">Öffentliche Sammelfortschritte dieses Spielers.</div>
      </div>

      <h3 style="margin:14px 0 6px">Angelegte Ausrüstung</h3>
      <div class="v074-equipment">${equipmentHtml(p.equipment)}</div>
      ${!own?'<button class="btn" id="v074AddFriend" style="width:100%;margin-top:12px">Freundschaftsanfrage senden</button>':''}
    `;
    wireClose();
    const add=document.querySelector('#v074AddFriend');
    if(add)add.onclick=()=>{try{v073SendFriendRequest(p.id,p.character_name)}catch(e){}};
    if(modal)modal.scrollTop=0;
  }

  function deadline(promise,ms){
    return Promise.race([
      Promise.resolve(promise).then(value=>({ok:true,value}),error=>({ok:false,error})),
      new Promise(resolve=>setTimeout(()=>resolve({ok:false,timeout:true}),ms))
    ]);
  }

  async function robustOpen(id){
    const mySeq=++requestSeq;
    if(!showLoading())return;
    const sid=String(id||'');
    let own=false;
    try{
      const ownId=String(v073User?.id||s?.social?.playerId||localStorage.getItem('growLegendsPlayerId')||'');
      own=!!ownId&&sid===ownId;
    }catch(e){}

    /* Own profile must open from the authoritative local save immediately.
       Online mirrors are updated afterwards and never block the UI. */
    if(own){
      try{
        const p=(typeof v073ProfilePayload==='function'?v073ProfilePayload():null);
        if(p){
          renderProfile({...p,id:(v073User?.id||p.id||s?.social?.playerId||sid)});
          setTimeout(()=>{
            try{if(typeof v073SyncProfile==='function')void deadline(v073SyncProfile(true),4500)}catch(e){}
            try{if(typeof v649SyncDungeonProgress==='function')void deadline(v649SyncDungeonProgress(true),4500)}catch(e){}
            try{if(typeof v446SyncCombatPower==='function')void deadline(v446SyncCombatPower(true),4500)}catch(e){}
          },0);
          return;
        }
      }catch(e){console.warn(VERSION+' local own profile',e)}
    }

    /* Other players require Supabase, but every await has a hard deadline so
       the modal can never stay on "wird geladen" forever. */
    let ready=true;
    try{
      if(typeof v073Init==='function'){
        const init=await deadline(v073Init(),3500);
        ready=!!(init.ok&&init.value);
      }
    }catch(e){ready=false}
    if(mySeq!==requestSeq)return;
    if(!ready||typeof v073Db==='undefined'||!v073Db){showError(id,'Online-Verbindung ist momentan nicht bereit.');return}

    try{
      const q=v073Db.from('profiles')
        .select('id,character_name,class_id,class_name,level,bosses,gear_score,dungeons,combat_power,equipment,dungeon_progress,worldboss_attempts,worldboss_wins,pvp_buds,pvp_wins,pvp_losses,pvp_fights')
        .eq('id',id).single();
      const res=await deadline(q,6500);
      if(mySeq!==requestSeq)return;
      if(!res.ok){
        showError(id,res.timeout?'Der Server antwortet zu langsam.':'Die Profildaten konnten nicht abgerufen werden.');
        return;
      }
      const result=res.value||{};
      if(result.error||!result.data){showError(id,'Für diesen Spieler konnten keine Profildaten geladen werden.');return}
      renderProfile(result.data);
    }catch(e){
      if(mySeq!==requestSeq)return;
      console.warn(VERSION+' profile load',e);
      showError(id,'Die Online-Verbindung wurde unterbrochen.');
    }
  }

  /* Replace the accumulated historical blocking wrapper chain. The existing
     V6.52 MutationObserver still decorates every newly rendered profile, so the
     Grow-Legends redesign and item renderer remain unchanged. */
  try{
    v074OpenProfile=robustOpen;
    window.v074OpenProfile=robustOpen;
    window.__v655PlayerProfileLoadFix=true;
  }catch(e){console.error(VERSION+' install',e)}
})();

